using System.Data;
using HRM.DAL;
using HRM.DTO;
namespace HRM.BUS;
public sealed class DepartmentService{private readonly DepartmentRepository repo=new();public List<Department> GetAll()=>repo.GetAll();public void Save(Department d,bool n){if(string.IsNullOrWhiteSpace(d.TenPB))throw new ArgumentException("Tên phòng ban không được để trống.");repo.Save(d,n);}public void Delete(int id)=>repo.Delete(id);}
public sealed class EmployeeService{private readonly EmployeeRepository repo=new();public List<Employee> Search(string k="",int? pb=null)=>repo.Search(k,pb);public void Save(Employee e,bool n){if(string.IsNullOrWhiteSpace(e.HoTen))throw new ArgumentException("Họ tên không được để trống.");if(e.LuongCoBan<=0)throw new ArgumentException("Lương cơ bản phải lớn hơn 0.");if(e.HeSoLuong<=0)throw new ArgumentException("Hệ số lương phải lớn hơn 0.");if(e.CCCD?.Length>20)throw new ArgumentException("CCCD tối đa 20 ký tự.");repo.Save(e,n);}public void Delete(int id)=>repo.Delete(id);}
public sealed class AttendanceService{private readonly AttendanceRepository repo=new();public DataTable Load(string m)=>repo.LoadMonth(m);public int Save(DataTable t,string m){if(repo.IsLocked(m))throw new InvalidOperationException("Tháng đã chốt lương, không thể sửa chấm công.");foreach(DataRow r in t.Rows){if(r.RowState==DataRowState.Deleted)continue;double days=Convert.ToDouble(r["SoNgayCong"]),ot=Convert.ToDouble(r["SoGioOT"]);if(days<0||days>31)throw new ArgumentException("Số ngày công phải từ 0 đến 31.");if(ot<0||ot>300)throw new ArgumentException("Số giờ OT phải từ 0 đến 300.");}return repo.Save(t,m);}public bool IsLocked(string m)=>repo.IsLocked(m);}
public sealed class PayrollService{private readonly PayrollRepository repo=new();public int Close(string m)=>repo.CloseMonth(m);public List<PayrollRow> GetMonth(string m)=>repo.GetMonth(m);}
